namespace HollowSeven.Editor { public static class CasinoBuilder {
    private static readonly string Root=ProjectSetup.Root;private static Transform _room;private static Material _brass,_wood,_velvet,_black,_ivory,_felt,_amber,_red,_green,_cloth;private static int _meshId;
    private static Color C(string h)=>UIFactory.Hex(h);
    private static Material Mat(string name,string hex,float metallic=0,float smooth=.3f,string emission=null){string path=Root+"/Materials/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.color=C(hex);mat.SetFloat("_Metallic",metallic);mat.SetFloat("_Smoothness",smooth);if(emission!=null){mat.EnableKeyword("_EMISSION");mat.SetColor("_EmissionColor",C(emission)*3);}return mat;}
    private static GameObject Primitive(string name,PrimitiveType type,Vector3 pos,Vector3 scale,Material mat,Transform parent=null){var go=GameObject.CreatePrimitive(type);go.name=name;go.transform.SetParent(parent??_room,false);go.transform.localPosition=pos;go.transform.localScale=scale;go.GetComponent<Renderer>().sharedMaterial=mat;var collider=go.GetComponent<Collider>();if(collider!=null)Object.DestroyImmediate(collider);return go;}
    private static GameObject Box(string name,float x,float y,float z,float sx,float sy,float sz,Material mat,Transform p=null)=>Primitive(name,PrimitiveType.Cube,new Vector3(x,y,z),new Vector3(sx,sy,sz),mat,p);
    private static GameObject Sphere(string name,Vector3 pos,Vector3 scale,Material mat,Transform p=null)=>Primitive(name,PrimitiveType.Sphere,pos,scale,mat,p);
    private static GameObject Cylinder(string name,Vector3 pos,Vector3 scale,Material mat,Transform p=null)=>Primitive(name,PrimitiveType.Cylinder,pos,scale,mat,p);
    private static GameObject MeshObject(string name,Mesh mesh,Vector3 position,Material mat,Transform parent=null){string path=Root+"/Art/Placeholders/Mesh_"+(_meshId++)+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old!=null){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(parent??_room,false);go.transform.localPosition=position;go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=mat;return go;}
    private static Mesh RingMesh(float radius,float tube,int segments=64,int sides=8){var v=new Vector3[segments*sides];var uv=new Vector2[v.Length];var tri=new int[segments*sides*6];int k=0;for(int i=0;i<segments;i++)for(int j=0;j<sides;j++){float a=i*Mathf.PI*2/segments,b=j*Mathf.PI*2/sides;int n=i*sides+j;v[n]=new Vector3(Mathf.Cos(a)*(radius+Mathf.Cos(b)*tube),Mathf.Sin(b)*tube,Mathf.Sin(a)*(radius+Mathf.Cos(b)*tube));uv[n]=new Vector2(i/(float)segments,j/(float)sides);int p=i*sides+(j+1)%sides,q=((i+1)%segments)*sides+j,r=((i+1)%segments)*sides+(j+1)%sides;tri[k++]=n;tri[k++]=p;tri[k++]=q;tri[k++]=p;tri[k++]=r;tri[k++]=q;}var m=new Mesh{name="Turned brass ring"};m.vertices=v;m.uv=uv;m.triangles=tri;m.RecalculateNormals();return m;}
    private static GameObject Ring(string name,Vector3 pos,float radius,float tube,Material mat,Transform p=null)=>MeshObject(name,RingMesh(radius,tube),pos,mat,p);
    private static Mesh Sector(float inner,float outer,float start,float end){var v=new List<Vector3>();var tri=new List<int>();const int slices=3;for(int i=0;i<=slices;i++){float a=Mathf.Lerp(start,end,i/(float)slices)*Mathf.Deg2Rad;v.Add(new Vector3(Mathf.Cos(a)*inner,0,Mathf.Sin(a)*inner));v.Add(new Vector3(Mathf.Cos(a)*outer,0,Mathf.Sin(a)*outer));if(i<slices){int n=i*2;tri.Add(n);tri.Add(n+2);tri.Add(n+1);tri.Add(n+1);tri.Add(n+2);tri.Add(n+3);}}var m=new Mesh{name="Roulette pocket"};m.SetVertices(v);m.SetTriangles(tri,0);m.RecalculateNormals();return m;}
    private static Light Light(string name,LightType type,Vector3 pos,Color colour,float intensity,float range){var go=new GameObject(name,typeof(Light));go.transform.SetParent(_room,false);go.transform.localPosition=pos;var l=go.GetComponent<Light>();l.type=type;l.color=colour;l.intensity=intensity;l.range=range;return l;}
    private static TextMeshPro Label(string name,string text,Vector3 position,float size,Color colour,Transform parent=null){var go=new GameObject(name,typeof(TextMeshPro));go.transform.SetParent(parent??_room,false);go.transform.localPosition=position;var t=go.GetComponent<TextMeshPro>();t.font=UIFactory.Font;t.text=text;t.fontSize=size;t.color=colour;t.alignment=TextAlignmentOptions.Center;t.rectTransform.sizeDelta=new Vector2(9,2);return t;}
    private static T Data<T>(string name) where T:ScriptableObject {string path=Root+"/Data/"+name+".asset";var asset=AssetDatabase.LoadAssetAtPath<T>(path);if(asset==null){asset=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(asset,path);}return asset;}
