        Label("NeonSign_HollowSeven","T H E   H O L L O W   S E V E N",new Vector3(0,3.65f,7.6f),6,C("D9AD61"));Label("SignSubline","EST.  19  /  77",new Vector3(0,3.2f,7.59f),2.5f,C("89723F"));
