        RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=C("352B35");RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.03f;RenderSettings.fogColor=C("120C10");
        var camera=GameObject.Find("PlayerCamera").GetComponent<Camera>();var rig=new GameObject("CameraRig").transform;rig.position=new Vector3(0,1.4f,-1.8f);camera.transform.SetParent(rig,false);camera.transform.localRotation=Quaternion.Euler(5.5f,0,0);camera.fieldOfView=50;camera.nearClipPlane=.1f;camera.farClipPlane=40;camera.allowHDR=true;var cameraData=camera.GetUniversalAdditionalCameraData();cameraData.renderPostProcessing=true;cameraData.antialiasing=AntialiasingMode.FastApproximateAntialiasing;
