        foreach(var comp in profile.components)Object.DestroyImmediate(comp,true);profile.components.Clear();var bloom=profile.Add<Bloom>();bloom.intensity.Override(.6f);bloom.threshold.Override(1);var vignette=profile.Add<Vignette>();vignette.intensity.Override(.3f);vignette.smoothness.Override(.5f);var grade=profile.Add<ColorAdjustments>();grade.saturation.Override(-10);grade.contrast.Override(10);var grain=profile.Add<FilmGrain>();grain.intensity.Override(.15f);foreach(var comp in profile.components)AssetDatabase.AddObjectToAsset(comp,profile);volume.sharedProfile=profile;
