    [MenuItem("Hollow Seven/Polish Existing Casino")]
    public static void Polish(){
        _room=GameObject.Find("Casino3D").transform;_meshId=300;_brass=Mat("M_Brass","A38950",.7f,.43f);_black=Mat("M_Ceiling","09070D");_cloth=Mat("M_Dealer_Cloth","12101B");_wood=Mat("M_Wood_Mahogany","291A19",0,.4f);_velvet=Mat("M_Wall_Velvet","250C18");_ivory=Mat("M_Mask","CEC6B3",.05f,.3f);
        var old=_room.Find("ArtPolish");if(old!=null)Object.DestroyImmediate(old.gameObject);var root=new GameObject("ArtPolish").transform;root.SetParent(_room,false);
        var sign=_room.Find("NeonSign_HollowSeven");if(sign!=null)sign.gameObject.SetActive(false);var sub=_room.Find("SignSubline");if(sub!=null)sub.gameObject.SetActive(false);
        var curtain=Mat("M_Curtain","290D22",0,.18f);foreach(float side in new[]{-1f,1f}){for(int i=0;i<9;i++)Cylinder("VelvetFold_"+side+"_"+i,new Vector3(side*(4.55f+i*.23f),2.7f,7.52f+(i%2)*.06f),new Vector3(.34f,2.1f,.18f),curtain,root);Box("CurtainRail",side*5.5f,4.8f,7.4f,2.4f,.07f,.12f,_brass,root);
            var diamond=Box("DecoDiamond",side*2.35f,2.65f,7.65f,.6f,.6f,.025f,_brass,root);diamond.transform.localRotation=Quaternion.Euler(0,0,45);var inset=Box("DecoDiamondInset",side*2.35f,2.65f,7.61f,.56f,.56f,.025f,_black,root);inset.transform.localRotation=Quaternion.Euler(0,0,45);
            Cylinder("FarTable",new Vector3(side*5,.7f,4.8f),new Vector3(2.2f,.05f,2.2f),_wood,root);Cylinder("FarTablePedestal",new Vector3(side*5,.35f,4.8f),new Vector3(.3f,.35f,.3f),_wood,root);
        }
        var dealer=_room.Find("Dealer");var shirt=dealer.Find("ShirtFront");shirt.localScale=new Vector3(.12f,.28f,.015f);var tie=dealer.Find("Tie");tie.localScale=new Vector3(.022f,.2f,.02f);
        // Sculpt the coat silhouette with separate shoulder and lapel pieces.
        Sphere("ShoulderL",new Vector3(-.19f,1.37f,2.47f),new Vector3(.22f,.18f,.28f),_cloth,root);Sphere("ShoulderR",new Vector3(.19f,1.37f,2.47f),new Vector3(.22f,.18f,.28f),_cloth,root);
        foreach(float side in new[]{-1f,1f}){var lapel=Box("Lapel",side*.085f,1.33f,2.29f,.075f,.25f,.025f,_black,root);lapel.transform.localRotation=Quaternion.Euler(0,0,side*18);}
        var grin=new GameObject("Mask_Grin").transform;grin.SetParent(dealer,false);for(int i=0;i<12;i++){float x=-.04f+i*.08f/11;float y=1.625f+x*x*12;var piece=Box("Smile_"+i,x,y,2.326f,.008f,.006f,.008f,_black,grin);piece.transform.localRotation=Quaternion.Euler(0,0,x*1000);}
        var director=_room.GetComponent<CasinoDirector>();director.Grin=grin.gameObject;director.CalmMouth=dealer.Find("Mouth").gameObject;grin.gameObject.SetActive(false);
        // Flat pockets should not cast self-shadow acne into the adjacent pocket.
        foreach(var render in director.Rotor.GetComponentsInChildren<Renderer>()){render.shadowCastingMode=ShadowCastingMode.Off;render.receiveShadows=false;}
        var tex=new Texture2D(128,128,TextureFormat.RGBA32,false);for(int y=0;y<128;y++)for(int x=0;x<128;x++){float d=Vector2.Distance(new Vector2(x,y),new Vector2(63.5f,63.5f))/64;float a=Mathf.Pow(Mathf.Clamp01(1-d),3);tex.SetPixel(x,y,new Color(1,1,1,a));}tex.Apply();string path=Root+"/Art/Placeholders/SoftCircle.png";File.WriteAllBytes(path,tex.EncodeToPNG());Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        var mist=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/M_Mist.mat");if(mist==null){mist=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));AssetDatabase.CreateAsset(mist,Root+"/Materials/M_Mist.mat");}mist.SetTexture("_BaseMap",texture);mist.SetColor("_BaseColor",Color.white);mist.SetFloat("_Surface",1);mist.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);mist.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);mist.SetFloat("_ZWrite",0);mist.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mist.renderQueue=3000;
        var fog=new GameObject("MistBack",typeof(ParticleSystem)).GetComponent<ParticleSystem>();fog.transform.SetParent(root,false);fog.transform.localPosition=new Vector3(0,.4f,5.5f);fog.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=fog.main;main.startLifetime=20;main.startSpeed=.04f;main.startSize=new ParticleSystem.MinMaxCurve(3,5);main.startColor=new Color(.42f,.49f,.55f,.16f);main.maxParticles=40;main.simulationSpace=ParticleSystemSimulationSpace.World;main.prewarm=true;var emission=fog.emission;emission.rateOverTime=2;var shape=fog.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(10,.6f,2);fog.GetComponent<ParticleSystemRenderer>().sharedMaterial=mist;
        EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();
    }
